  "system.auto.mkzit3.73": "既存のローカルな作業のみです。権限、処理記録、ナビゲーションの許可を示すものではありません。",
  "system.auto.1n5r82s.70": "ローカルな表示のみです。会話のメッセージやツールへのリクエストではありません。",
  "system.auto.3wbtph.76": "既存の管理主体を参照します。ナビゲーションによって、その作業を受領済みにしたり破棄したりしてはいけません。",
  "system.auto.d196id.89": "内容を含めずに呼び出し元の受け入れ条件を確認します。元のメモ、レビュー、修正の管理主体はここに残ります。",
  "system.auto.j6sudy.92": "まったく同じルートのオープンを待ちます。ストアでのルート変更が成功しても、ビューアーへの到達が確認されたことにはなりません。",
  "system.auto.1bm0iyt.91": "ローカルな作業のみです。false という値は、ソース、読み取り、ルートが現在も有効であることや、作成権限があることを保証しません。",
  "system.auto.1vns05w.99": "現在の作成済み出力1件の既存の状態だけを表示します。スナップショットを作成したり、アクションの権限を付与したりすることはありません。",
  "system.auto.1ixc2m9.95": "既存の同じローカル実行処理を使用します。画面間のルーティングは、引き続き状態を持たないオープン用ヘルパーが担当します。",
  "system.auto.mffe2n.86": "既存の準備用エントリーポイントです。ネイティブなオープン処理の間も、呼び出し元が引き続き管理します。",
  "system.auto.1dlpcpe.28": "デバイスのキューは未確認です",
  "system.auto.1ssjjvw.195": "このページではCanvasの同期を一時停止し、デバイスのストレージで非公開の下書き本文を削除して元の参照を保存しています。再読み込み後に一時停止が維持されるかは、まだ確認されていません。元の変更を再送しないでください。",
  "system.auto.1yofwuk.49": "Canvasの同期を一時停止中 · 元の参照を保持",
  "system.auto.1w0ppjw.143": "Canvasの非公開の下書き本文は、このデバイスのキューから取り除かれました。元のバッチ参照は保持され、未確認の変更は再送されません。",
  "system.auto.1lzk80v.175": "このページではCanvasの同期を一時停止しています。デバイスのストレージでは、非公開の下書き本文の削除や、再読み込み後の一時停止の維持を確認できませんでした。元の変更を再送しないでください。",
  "system.auto.e7k4f4.75": "表示されたアクションが現在の表示に属するかを確認する任意のチェックです。権限を付与するものではありません。",
  "system.auto.1lv00pf.71": "識別情報のみです。下書き自体は、この接続済みエディターが引き続き管理します。",
