  "system.auto.8an6rp.46": "範囲の周囲をドラッグして切り抜きの形を描きます。",
  "system.auto.1mvreps.21": "ブロックをドラッグして並べ替え",
  "system.auto.c70j66.122": "キャンバスの何もない場所からドラッグして範囲を選択します。カードは引き続きクリックやドラッグが可能です。Shift を押しながら選択範囲を追加し、完了したら Escape を押してください。",
  "system.auto.ongqjn.29": "ドラッグするか矢印キーで並べ替え",
  "system.auto.cna0nm.65": "カードの角をドラッグしてサイズ変更 · 矢印キーで細かく調整 ·",
  "system.auto.5gb57g.67": "選択範囲をドラッグして移動します。辺または角を引っ張ってサイズを変更します。",
  "system.auto.c8g72k.83": "ドラッグして対象範囲を自由な形で描き、角や辺を引っ張って形を整えます。",
  "system.auto.2zydf2.123": "ドラッグして対象範囲を長方形で描きます。選択した長方形をドラッグして移動するか、辺や角のハンドルを使ってサイズを変更します。",
