  "system.auto.827e70.178": "選択したすべてのスタディがロックされ、コンポジションで使用されることを示すイベントが必要です。有料の処理を承認する前に、イベントストリームを長くするか、スタディまたはプロバイダーのマイルストーンを減らしてください。",
