  "system.auto.1229tpt.226": "既存の承認済み参照資料は、可能な限り並行して処理されます。トランジションにはテキストによる指示を使用します。プロバイダーは開始・終了フレームのネイティブなロックや、動画フレームの抽出に対応していません。完成した結果は、順番に並んだシーンリールになります。",
