  "system.auto.ghnwqc.145": "アダプターの契約は設定済みです。有料の再試行には、別途明示的な承認が必要です。この確認ページから暗黙的に開始されることはありません。",
  "system.auto.1b055hx.149": "このアダプターにより、プロバイダーの拡張内容を明示して監査できるようになります。各機能カテゴリと標準的なプロンプト手法の合格基準もすべて維持されます。",
  "system.auto.1ng2rfe.38": "アプリの画面が自動的に切り替わります。",
  "system.auto.1hwxvrf.44": "アプリの実行環境はシナリオの開始地点で待機しています。",
  "system.auto.6wmau7.361": "この監査ではラベルではなく関係性を検証します。画面を横断する公平なストーリー、再利用可能な Library のコンテキストから選択された Canvas の統合案への変換、成果物の形式ごとに異なる制作ブリーフと構成、複数のプロンプト候補の評価、空間的な編集、修正時の負荷、参照ピクセルの受け渡し、再開、運用上の復旧、そして利用可能な独立した架空のアカウントが対象です。",
  "system.auto.tkftxw.9": "制作ブリーフ",
  "system.auto.qszcq6.95": "このグループが定義する、登場人物、場所、章、オブジェクトなど、成果物の特定の要素です。",
  "system.auto.19oaikb.38": "比較を完了できませんでした。",
  "system.auto.px8pq5.195": "保持されたコーパス全体でプロバイダー側のエラーは発生していませんが、クリエイティブの品質と意味の保持に関する基準を満たしていません。次の有料評価を実施する前に、新しいバージョンのアダプターを準備して事前確認してください。",
  "system.auto.1vuk10b.48": "基本のフローを確認または生成できます。",
  "system.auto.9ktj96.19": "現在のアダプター",
  "system.auto.17o6rpl.54": "状態が進んでも、現在の画面は固定されたままです。",
