  "system.auto.1b5au6u.118": "この応答の根拠となった決定は、すでに利用できません。実際には存在しない出典を付けずに、応答は引き続き表示されます。",
  "system.auto.hktde1.68": "上記の決定論的シナリオは引き続き完全な状態で、無料で構築できます。",
