  "system.auto.177yxbp.164": "何もレンダリングせずに、ドキュメントをボード上に置いておくことができます。次の判断に役立つタイミングで、画像、ストーリー、シーン、スライド資料、絵コンテ、または動画を作成してください。",
  "system.auto.u65cu9.49": "ドキュメントの構成が整い、次に進める状態です",
  "system.auto.59r741.35": "このドキュメントからはまだ何も生成されていません",
  "system.auto.1a4uwpe.48": "ドキュメントをビジュアル作品に変換できる状態です。",
  "system.auto.1x6v5rz.103": "ドキュメントはアクティブなプロジェクト画面から非表示になります。イベント履歴は引き続き再生でき、Undo で元に戻せます。",
  "system.auto.iaozzj.71": "ドキュメントに、意図、現実、表現、制約が結び付きました。",
  "system.auto.da8ek9.20": "ドキュメントのプレビュー",
  "system.auto.4gh0d0.170": "選択した決定事項の再利用可能なコピーがドキュメントにまとめられ、このボードにすぐ表示されます。この操作では画像モデルは呼び出されず、生成予算も消費されません。",
  "system.auto.1j66io9.157": "ドキュメントと、そのクリエイティブ上の決定および成果物が、アクティブなプロジェクトから削除されます。別のドキュメントが自動的に開き、Undo でこのドキュメントを元に戻せます。",
  "system.auto.1hpvzf1.65": "保存済みの下書きが、このストリーミング画像に自動的に置き換わります。",
  "system.auto.ac1dhz.129": "エディターが、色、雰囲気、レイアウト、素材、照明、空間に関する手がかりを準備します。どれをプランに取り入れるかは、ご自身で選択できます。",
  "system.auto.120xpe4.30": "必要な証拠がすべてそろいました",
  "system.auto.kgv9mg.154": "登録されたアダプターと完全に同一のバージョンが、変更されていないすべての適格性検証に合格しました。改ざんできない証拠を管理者が確認し、承認できます。",
  "system.auto.t9odzb.70": "プロバイダーへの失敗したリクエストに関連付けられた、保存済みの正確なプロンプトです。",
