  "system.auto.1xbz3av.99": "インタビューでは一度に数件の質問に集中します。このマップでは、保存したほかの判断もすべて確認できます。",
  "system.auto.7kcub6.53": "運用上の確認のため、このジョブは失敗として記録されます。",
  "system.auto.1rx69op.195": "直近の範囲限定検索では、完全な適格性審査に合格できませんでした。プロンプト、プロバイダー、安全性、費用、評価の記録は保持されています。このバージョンのアダプターは再実行も承認もできません。",
