  "system.auto.zk3ffj.143": "元のバイトデータは非公開ストレージに保持されます。SHA-256 コンテンツハッシュと引用したすべての抜粋は、権利の記録と合わせて検証されます。",
  "system.auto.btpz5t.88": "元の全文は利用できなくなっています。保持されているタイトルと要約を表示します。",
  "system.auto.1t7hmu6.175": "元のデータは変更されません。推定された判断には承認が必要で、参照素材の権利は決して推定されません。この無料シミュレーションでは、プロバイダーの呼び出しや支出の承認はできません。",
  "system.auto.yix2qs.75": "元のデータは変更されません。保存した編集内容はすべて、今後の作業に反映されます。",
  "system.auto.1fr7jmj.59": "このプロジェクトで実現する成果、判断、または変化",
  "system.auto.agvzrw.34": "対比較評価が承認されました。",
  "system.auto.r97x2e.11": "画像",
  "system.auto.tnjhrb.124": "プランを更新しました。作業用プレビューは別途作成しているため、画像の完成を待たずに会話を続けられます。",
  "system.auto.qakbuo.297": "プランナーは、再利用可能な Wikimedia Commons の画像を選択するか、GPT Image で低品質の参照画像を作成できます。サーバーはアップロードイベントの前に画像を検証し、ハッシュ化して保存します。ライセンス付きの素材には出典が保持されます。ウェブから取得できない場合は、予算に計上済みの生成された参照画像に切り替わります。",
  "system.auto.gjade.70": "プレビューに構成だけでなく、言葉遣いや雰囲気も反映されるようになりました。",
  "system.auto.68m0ny.127": "前回のパイロット運用は終了しました。組織のオーナーが新しい管理対象コホートを明示的に開始するまで、有料の処理はブロックされます。",
  "system.auto.yuv5u2.154": "前回のレポートは変更されません。この候補にはその調査結果が組み込まれ、既存の基準を緩和することなく、機能ごとの最低基準が追加されています。",
  "system.auto.1j5ja32.68": "ドキュメントを変更せずに、前回のセッションを要約しました。",
  "system.auto.1l4kw8z.60": "プロンプトをコピーできませんでした。選択して手動でコピーしてください。",
  "system.auto.1pgyk60.75": "プロバイダーの結果を確定中のため、安全に停止できる段階を過ぎています。",
  "system.auto.1t85ddp.67": "プロバイダーを使用するワークフローが、公開エラーメッセージなしで失敗しました。",
  "system.auto.9vquyx.13": "参照素材",
  "system.auto.hz2zr6.127": "参照素材は変更されません。パレットを選択すると、この画像への出典付きで、独立したパレットブロックが新たに作成されます。",
  "system.auto.aidboo.167": "登録済みの v52 アダプターは、固定された適格性審査をすべて通過しました。証拠を確認し、Fal の利用権限の参照情報を追加して、以下に管理者の承認を記録してください。",
  "system.auto.18it7n1.53": "リプレイで、次に利用できる復帰ポイントを準備しています。",
  "system.auto.lrwr6p.103": "リプレイの投影では、ハイブリッド論理クロックの最大値が選択されます。元のイベントはすべて確認できます。",
  "system.auto.8b6ke8.277": "指定された TC39 Signals の polyfill と signal-utils が、ストアと合成ストリームビルダーを支えています。どちらの上流プロジェクトも API を実験的なものとしているため、Forma は小さなストア境界の内側にそれらを隔離しています。Lit コンポーネントは、パッケージ固有の内部実装ではなく、ストアの契約を利用します。",
  "system.auto.1tl2mjj.45": "保持された成果物の内容は利用できません。",
  "system.auto.1g3s3w7.64": "ランナーは読み取り専用です。状態はリプレイの投影から取得されます。",
  "system.auto.dbd1jb.85": "同じコレクションにドキュメントを含めることもできます。アクセス権はプロジェクトのコンテナに従います。",
  "system.auto.1f7crgw.122": "同じクリエイティブの方向性から、元のドキュメントを変更せずに、ストーリー、プレゼンテーション、絵コンテ、動画を作成できます。",
  "system.auto.1brep9n.65": "同じプロジェクトボードを、アクセシブルでキーボード操作しやすい順序で表示します。",
  "system.auto.qanswi.186": "スカウトは観察、レポート領域での生成、予算の消化を行えますが、方向性の決定や作品のコレクションへの登録はできません。これらは機能の不足ではなく、意図的な制限です。",
  "system.auto.1qjl2ti.64": "サーバーがこのレンダリングを受け付け、次の段階を準備しています。",
  "system.auto.j68f18.63": "現在のロールでは、この空間ワークスペースへのアクセスがサーバーから許可されていません。",
  "system.auto.7xsiny.104": "サーバーが最新のクリエイティブプランを処理しています。完成した下書きの前に、初期画像が表示されます。",
  "system.auto.b2pwdr.88": "実行中に進捗が報告されている間、サーバーはこの記録を 10 秒ごとに更新します。",
  "system.auto.1cu04b2.176": "サーバーは、管理者、有効期限内の一度限りの承認、直接操作するユーザーによる証明を要求します。エージェントのロールや、自動化またはテスト実行を申告するリクエストは拒否されます。",
  "system.auto.1qztkpw.297": "元画像には 2 種類の計算結果が重ねて表示されます。オレンジ色の長方形と塗りつぶされたマーカーは注目領域を、白抜きのマーカーは顕著性の重心を表します。隣り合う 2 つのプレビューでは、それぞれの点を同じ切り抜き形状に適用し、出力品質と計算コストのトレードオフを直接比較できます。",
  "system.auto.177hoo1.22": "絵コンテとすべての",
  "system.auto.spb3ob.89": "絵コンテと、リンクされているすべてのフレームがまとめて削除されます。元に戻すと、すべて復元されます。",
  "system.auto.1y1skid.56": "ストリームに開発パス全体を含めることはできません。",
  "system.auto.10fv6go.105": "以前の失敗時に送信されたプロンプトは利用できないか、非公開での保持期間が終了しています。",
  "system.auto.195qbp9.100": "最初に自由な意図を入力するのは、固定の質問票ではその後の設定が画一的になってしまうためです。",
