  "system.auto.13ysmuj.180": "変更していない 50 ケースの比較で、総合、参照、指示、能力、プロンプト手法のすべての基準を満たしました。最良の結果を出した本番構成がそのまま登録されています。",
  "system.auto.1my2nnk.46": "モック全体は別の ID に属しています。",
