  "system.auto.1hw8gj9.150": "これらは、ユーザーが実際に体験する可能性のある操作と結果です。コンパイラー、レジストリ、インデックス作成に関する非表示のイベントも、引き続き投影に含まれます。",
  "system.auto.aooveu.121": "これらは、試行が失敗する前に記録・保持された入力です。ドキュメントの現在の状態から再構成されたものではありません。",
