  "system.auto.x5a7xf.37": "%使用済みです。生成処理では最大で次の量が確保されます：",
  "system.auto.7yef3w.181": "バランスの取れたエンドツーエンドのキャンペーンです。Libraryのコンテキストの再利用、Canvasでの探索的な合成、ドキュメントの改善、あらゆる形式での出力、判断、記憶、作業の再開、運用の復旧を網羅します。",
  "system.auto.16ycr9a.28": "実際の作業に近いセッション",
  "system.auto.31zt4l.59": "雰囲気やビジュアルを重視する作品に適した、映画のようなダークトーンの表現です。",
  "system.auto.1faalba.74": "明確な判断によって、その後のすべての成果物に意味のある方向性が生まれます。",
  "system.auto.1h5iank.91": "ドキュメントの目的、登場人物、舞台設定、制約に沿って構成された、完結した物語です。",
  "system.auto.16cdrmr.32": "プロジェクトボードでの一連の作業セッション",
  "system.auto.t40q9o.73": "画像の構成段階が明示されており、事前の検討は依頼されていません。",
  "system.auto.1okh7m.75": "発表者のメモとビジュアルの方向性を含む、簡潔なプレゼンテーション用の構成です。",
  "system.auto.187px31.60": "調査、エビデンス、計画に適した、クールで体系的なデザインです。",
  "system.auto.rz6myk.90": "プロバイダーでの追加処理を開始する前に、費用または権限に関する判断を確認する必要があります。",
  "system.auto.6l305a.243": "作成者はコンテンツを開き、移動、選択、整理、作成、共同作業、ヘルプの依頼、ドキュメントの準備、レンダリング、確認、作業の復旧を行います。有意義な操作はすべて計測されますが、カーソルの軌跡や生の入力データは保存されません。",
  "system.auto.1frok8u.214": "作成者は曖昧な目標から作業を始め、1つの固定コンテキストを作成します。そのうえで、出所を共有し、エクスポートの記録が明示された画像、物語、シーン、プレゼンテーション、絵コンテ、動画を用途に応じて活用します。",
  "system.auto.71pbkw.53": "意図的に構成された色彩とトーンの組み合わせ",
  "system.auto.wfjhxd.43": "作品で避けるべき失敗パターンまたはモチーフ",
  "system.auto.1l28vr8.23": "人々が去った後のグラウンド",
  "system.auto.1mozq04.23": "人々が去った後のグラウンド",
  "system.auto.fsgk08.105": "完成した成果物を、権利に配慮しながら、何もない状態から仮想的に作り上げる、取り消し可能なワークフローに変換できます。",
  "system.auto.1kyjq4d.193": "Formaによる生成結果の保存中に、ローカルイベントの記録またはデータベースへの書き込みに失敗しました。プロバイダーの障害は報告されていません。サポートにお問い合わせいただくか、サーバーの永続化とイベント保存に関する診断情報をご確認ください。",
  "system.auto.gz83kn.80": "低品質の下書きには、作成者が承認した意図と、最高品質の成果物までの過程が含まれます。",
  "system.auto.bucbhq.75": "名前付きの選択範囲が、空間的な配置に意味を持たせないことを明示したうえでコンパイルされます。",
  "system.auto.1rd2hm.45": "より新しいワークスペースのセッションをすでに読み込んでいます。",
  "system.auto.12lz8mb.75": "設定済みの動画プロバイダーによってレンダリングされた、再生可能な映像表現です。",
  "system.auto.huju6j.35": "準備済みのCanvasドキュメントが先行します：",
  "system.auto.32whni.92": "以前のリクエストは、有料処理の開始前にブロックされました。プロバイダーの問題を解決してから、もう一度お試しください。",
  "system.auto.s6y8bg.72": "アクションとセリフを含む、制作現場で使用できる映画またはテレビ番組のシーンです。",
  "system.auto.az96pk.41": "プロジェクトとドキュメントは次のすべてを経て発展します：",
  "system.auto.1g314sy.75": "有望な試みを、最初からやり直すことなく完成した成果物へと発展させられます。",
  "system.auto.1jj1luu.145": "再開時のブリーフ、範囲を限定したScoutの実行、人による判断、承認済みのコンテキストによって、エージェントがドキュメントを無断で編集することなく、セッションをまたいで作業を引き継げます。",
  "system.auto.hhoo0j.160": "参照資料が編集可能なコンテキストに変換され、下書きが意図的に最高品質へ引き上げられます。完成した成果物には、批評、ライブラリ、エクスポートの記録が付随します。",
  "system.auto.zbg2zm.93": "この結果を対象とするリクエストはまだ処理中です。別のドキュメントや成果物で完了させることはできません。",
  "system.auto.bxjmvu.38": "再利用可能な、洗練された控えめな仕上げ",
  "system.auto.uhqvi2.209": "実データに基づく保存済みのモックに、分離された架空の作成者が割り当てられます。サインイン中の管理者がそのアカウントに入り、保護された変更を1件確認してから、合成データを通常のアカウントに持ち込むことなく元に戻ります。",
  "system.auto.wcax7k.79": "選択した生成画像を利用できないため、ドキュメントは変更されませんでした。",
  "system.auto.hcnrqd.70": "選択した成果物を利用できないため、ドキュメントは変更されませんでした。",
  "system.auto.cwdwfz.59": "セッションの切り替えによって、人が承認した有益な再開方法が提示されます。",
  "system.auto.vtxnep.66": "ショットごとのプレビズを、つながりのある下書きフレームとしてレンダリングしたものです。",
  "system.auto.1lzrt0y.91": "ドキュメント、判断、参照資料、あらゆるクリエイティブな成果物を空間的に扱えるプロジェクトのワークスペースです。",
  "system.auto.1wra0hp.97": "参照情報、レイアウト領域、プロンプト設定を含む、機械で読み取り可能な安定した生成オブジェクトです。",
  "system.auto.mryzaz.85": "ドキュメントの判断内容と関係性を保持する、安定したノード階層です。",
  "system.auto.1dds7wl.209": "提出済みの最終プレゼンテーションが、仮想的であることを明示し、権利に配慮した一連のプロセスに変換されます。推測されたコンテキスト、別のクリエイティブな方向性、承認済みの判断、レビュー、エクスポート、成果物を入力として再利用する新たな改訂が含まれます。",
  "system.auto.18mq7hd.179": "ユーザーは曖昧なアイデアについて話し合い、Liveプレビューを一時停止し、2つのローカル対象を直接編集します。複数のプロンプトを比較して成果物を確定し、一度離れた後、有益なブリーフを手がかりに作業を再開します。",
  "system.auto.1vuksmo.81": "検証済みの保存画像、出所、権利情報、コンテンツのハッシュ値を確認してから、モックに取り込みます。",
