  "system.auto.c0m3v4.138": "構造化された制作では、編集可能なエクスポートの上限である {MAX_MANAGED_PRESENTATION_SLIDES} 枚まで、作成済みの長いプレゼンテーションを保持できます。",
  "system.auto.1tmoygj.9": "概要",
