  "system.auto.x2ggib.135": "{predictedSlideCount} 枚のスライドプランは、作成済みの {authoredSlideCount} 枚の構成案を拡張したものです。追加するスライドは元の資料に基づいている必要があります。",
  "system.auto.6sp85k.197": "{value} のエビデンスは不合格として保持されます。直近の検索では、意味上の不一致とプロバイダーの安全性・信頼性の問題が確認されました。新しいバージョンを準備する前に、キャンペーンのエビデンスを確認してください。",
  "system.auto.rvl0fp.100": "絵コンテと、それにリンクされた {value} 件のフレームがまとめて削除されます。1回の取り消し操作ですべて復元できます。",
