  "system.auto.v8uuz3.118": "{itemCount}枚のスライドを指定しましたが、構造化ワークフローでは作成済みのスライド{predictedSlideCount}枚すべてが保持されます。",
  "system.auto.lnr6ue.135": "件の有料リクエスト（制限された検証および整合性の修正を含む）。初期予約額とアプリで適用される支出上限：",
  "system.auto.1r6h7b9.142": "Formaは、プロバイダーへのリクエストや修正を行う前に、アプリに残っている支出上限を確認します。これはプロバイダー側で適用される支出上限ではありません。",
  "system.auto.1ssottd.159": "過去に作成されたイベントの本文を、所有者ごとに管理される消去可能なストレージに移行しますか？イベントの識別情報、改訂履歴、プロジェクトの権限、完成した成果物は保持されます。",
  "system.auto.j2gqvj.209": "個人プロジェクトで作成したコンテキストと一時的な非公開の処理データを完全に消去しますか？完成した成果物、アップロード済みのファイル、組織内の共有作業、バックアップ、ほかのデバイスのデータは削除されません。",
  "system.auto.1anbigg.71": "この法的保全措置を解除しますか？解除すると、条件を満たした保存期限切れの証拠を削除できるようになります。",
  "system.auto.x2egvp.73": "閲覧権限のあるすべてのプロジェクトについて、暗号化されたスナップショットを作成しますか？",
  "system.auto.22u9cb.79": "この組織の復旧キーを更新しますか？既存のスナップショットは引き続き復号できます。",
  "system.auto.1om1shf.56": "この組織のプロビジョニングトークンを直ちに失効させますか？",
  "system.auto.1ps0xzg.106": "管理上の所有権を、条件を満たすこの管理者に移譲しますか？現在のプロジェクトセッションは終了します。",
  "system.auto.1qb2itm.159": "元に戻せない削除を実行する前に、この組織で過去に作成されたイベントだけを非公開の領域に移行しますか？ほかの組織や個人プロジェクトには影響しません。",
  "system.auto.1lug8ho.166": "この組織の対象プロジェクト、ソース、コンテキストパッケージ、出力の改訂履歴、メンバーシップ、復旧用スナップショットを完全に消去しますか？有効な法的保全措置がある場合は削除できません。",
  "system.auto.wlcjeh.61": "この生成は、{scope}の月間予算の残額を超えています。",
  "system.auto.1skaw5b.124": "{scope}の予算は {percent}% 使用される見込みです。生成のために最大 {reserved} が確保され、開始前の残額は {remaining} です。",
