  "system.auto.d8ccm.170": "参照画像から {seconds} 秒の動画を生成する有料処理を開始します。実際の画像 {count} 枚がプロバイダーに送信されます。残りの {descriptions} 件は、順序付けされた説明文としてのみ使用されます。",
